async function generateMetadata(
	props: Props,
	parent: ResolvingMetadata,
): Promise<Metadata> {
	const { slug } = await props.params
	const entry = await getAiCodingDictionaryEntry(slug)

	if (!entry) {
		return parent as Metadata
	}

	const title = `${entry.title} | ${AI_CODING_DICTIONARY_TITLE}`
	const description = entry.description || AI_CODING_DICTIONARY_DESCRIPTION
	const canonicalPath = `/ai-coding-dictionary/${entry.slug}`
	const ogImage = getAiCodingDictionaryOgImageUrl(title)

	return {
		title,
		description,
		applicationName: 'AI Hero',
		creator: 'Matt Pocock',
		publisher: 'AI Hero',
		category: 'Education',
		keywords: [
			entry.title,
			'AI coding dictionary',
			'AI coding glossary',
			'AI engineering vocabulary',
			entry.sectionTitle,
		],
		alternates: {
			canonical: canonicalPath,
		},
		openGraph: {
			title,
			description,
			url: canonicalPath,
			siteName: 'AI Hero',
			type: 'article',
			locale: 'en_US',
			images: [
				{
					url: ogImage,
					width: 1200,
					height: 630,
					alt: title,
				},
			],
		},
		twitter: {
			card: 'summary_large_image',
			title,
			description,
			images: [ogImage],
		},
	}
}
